css:
.card {
  width: 230px;
  height: 340px;
  background: #131313;
  border: 2px solid #569E67;
  border-radius: 40px;
}

.image {
  background-color: #1f1f1fa3;
  border-radius: 2.5em 2.5em 0em 0em;
  width: 100%;
  height: 37%;
  padding: 2px;
}

.image svg {
  width: 75%;
  margin-top: -335px;
  margin-left: 30px;
}

.productTitle {
  text-align: center;
  font-size: 22px;
  font-weight: bold;
  color: #569E67;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  margin-top: 10px;
}

.cost {
  text-align: center;
  margin-top: 10px;
  font-weight: bold;
  color: white;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
}

.radio-inputs {
  position: relative;
  margin-top: 20px;
  margin-left: 13px;
  display: flex;
  flex-wrap: wrap;
  border-radius: 0.5rem;
  background-color: #182b1c;
  box-sizing: border-box;
  box-shadow: 0 0 0px 1px rgba(0, 0, 0, 0.06);
  padding: 0.25rem;
  width: 200px;
  font-size: 14px;
}

.radio-inputs .radio {
  flex: 1 1 auto;
  text-align: center;
}

.radio-inputs .radio input {
  display: none;
}

.radio-inputs .radio .name {
  display: flex;
  cursor: pointer;
  align-items: center;
  justify-content: center;
  border-radius: 0.5rem;
  border: none;
  padding: .5rem 0;
  color: #fff;
  transition: all .15s ease-in-out;
}

.radio-inputs .radio input:checked + .name {
  background-color: #000;
  color: #569E67;
  font-weight: 600;
}

.addtocart {
  width: 100%;
  margin-top: 19px;
  padding: 15px;
  border: none;
  border-top: 2px solid #569E67;
  background-color: #131313;
  color: #569E67;
  font-weight: bold;
  font-size: 15px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  border-radius: 0px 0px 38px 38px;
  transition: 0.2s;
}

.addtocart:hover {
  background-color: #569E67;
  border-top: 2px solid transparent;
  color: #111111;
}
